with department_summary as (select dept_id, sum(case when level = 'L5' then 1 else 0 end) as l5_count, count(distinct salary) as unique_job_titles from employees where manager_id is not null group by dept_id) select d.location, d.dept_name, ds.l5_count, ds.unique_job_titles from departments d inner join department_summary ds on d.id = ds.dept_id where ds.unique_job_titles >= 4 order by l5_count
